class Solution {
public:
    int countDigits(int num) {
        int temp = num, ans = 0;
        while (temp > 0) {
            int d = temp % 10;
            if (d != 0 && num % d == 0) ans++;
            temp /= 10;
        }
        return ans;
    }
};

