            int d = temp % 10;
            if (d != 0 && num % d == 0) ans++;
            temp /= 10;
        }
        return ans;
    }
}

var countDigits = function(num) {
    let temp = num, ans = 0;
    while (temp > 0) {
        const d = temp % 10;
        if (d !== 0 && num % d === 0) ans++;
        temp = Math.floor(temp / 10);
    }
    return ans;
};
